     1|/**
     2| * Supabase Edge Function: send-sms
     3| *
     4| * Complete phone-auth OTP flow for VitaHero.
     5| *
     6| *   POST { action: "send_otp", phone: "+919876543210" }
     7| *     → Generates 6-digit OTP, stores salted hash in phone_otps table,
     8| *       sends SMS via Twilio. Returns { success, expiresIn: 300 }.
     9| *
    10| *   POST { action: "verify_otp", phone: "+919876543210", otp: "123456" }
    11| *     → Verifies OTP hash, creates/finds the Supabase Auth user (phone identity),
    12| *       generates a session, returns { success, access_token, refresh_token, user }.
    13| *
    14| * Twilio credentials are passed via x-twilio-account-sid / x-twilio-auth-token
    15| * headers from the Android app (injected at build time from Rork private env vars).
    16| */
    17|
    18|import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
    19|
    20|const corsHeaders = {
    21|  "Access-Control-Allow-Origin": "*",
    22|  "Access-Control-Allow-Headers":
    23|    "authorization, x-client-info, apikey, content-type, x-twilio-account-sid, x-twilio-auth-token",
    24|  "Access-Control-Allow-Methods": "POST, OPTIONS",
    25|};
    26|
    27|// ── Crypto ─────────────────────────────────────────────────
    28|
    29|async function sha256(text: string): Promise<string> {
    30|  const data = new TextEncoder().encode(text);
    31|  const buf = await crypto.subtle.digest("SHA-256", data);
    32|  return Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join("");
    33|}
    34|
    35|function generateOtp(): string {
    36|  const d = new Uint8Array(6);
    37|  crypto.getRandomValues(d);
    38|  return Array.from(d, (b) => (b % 10).toString()).join("");
    39|}
    40|
    41|function generatePassword(): string {
    42|  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$";
    43|  const arr = new Uint8Array(20);
    44|  crypto.getRandomValues(arr);
    45|  return Array.from(arr, (b) => chars[b % chars.length]).join("");
    46|}
