    98|
    99|Deno.serve(async (req: Request) => {
   100|  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
   101|
   102|  try {
   103|    const p = await req.json();
   104|    const action = p.action as string;
   105|
   106|    if (action === "send_otp") return await handleSendOtp(req, p);
   107|    if (action === "verify_otp") return await handleVerifyOtp(req, p);
   108|    // Legacy hook mode: GoTrue calls us with { phone, otp }
   109|    if (p.phone && p.otp) return await handleSendOtp(req, { ...p, action: "send_otp" });
   110|
   111|    return new Response(JSON.stringify({ error: "Use { action: 'send_otp' | 'verify_otp' }" }), {
   112|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   113|    });
   114|  } catch (err) {
   115|    console.error("send-sms error:", err);
   116|    return new Response(JSON.stringify({ error: "Internal server error" }), {
   117|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   118|    });
   119|  }
   120|});
