   122|// ── send_otp ───────────────────────────────────────────────
   123|
   124|async function handleSendOtp(req: Request, payload: Record<string, unknown>) {
   125|  const phone = norm((payload.phone as string) || "");
   126|  if (!phone || phone.length < 10) {
   127|    return new Response(JSON.stringify({ error: "Valid phone number required" }), {
   128|      status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   129|    });
   130|  }
   131|
   132|  let sid = Deno.env.get("TWILIO_ACCOUNT_SID") || req.headers.get("x-twilio-account-sid") || "";
   133|  let tok = Deno.env.get("TWILIO_AUTH_TOKEN") || req.headers.get("x-twilio-auth-token") || "";
   134|  if (!sid || !tok) {
   135|    return new Response(JSON.stringify({ error: "SMS provider not configured" }), {
   136|      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   137|    });
   138|  }
   139|
   140|  const otp = (payload.otp as string) || generateOtp();
   141|  const salt = crypto.randomUUID();
